INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(25601, 'John 16:2', 'John', 16, 2, '&nbsp;نو هغوئ به تاسو د عبادتخانو نه شړى، او بې‌شکه داسې وخت راتلونکے دے څوک چې تاسو قتلوى هغوئ به دا ګُمان کوى چې په دې کار کولو سره هغوئ د خُدائ پاک خِدمت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25602, 'John 16:3', 'John', 16, 3, '&nbsp;هغوئ به دا کارونه ځکه کوى چې هغوئ نۀ پلار پېژنى او نۀ ما.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25603, 'John 16:4', 'John', 16, 4, '&nbsp;خو ما دا خبرې تاسو ته ځکه وکړې چې کله دا کار پېښ شى نو تاسو ته به راياد شى چې ما تاسو د دې په حقله خبر کړى وئ. ما تاسو ته دا خبرې د اول نه ځکه ونۀ کړې ځکه چې زۀ تاسو سره وم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25604, 'John 16:5', 'John', 16, 5, '&nbsp;خو اوس زۀ هغه چا ته روان يم چا چې زۀ رالېږلے يم. اوس په تاسو کښې هيڅوک زما نه دا تپوس نۀ کوى چې تۀ چرته روان يې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25605, 'John 16:6', 'John', 16, 6, '&nbsp;خو دا کومې خبرې چې ما تاسو ته وکړې په هغې ستاسو زړونه غمژن شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25606, 'John 16:7', 'John', 16, 7, '&nbsp;خو زۀ تاسو ته رښتيا وايم چې دا ستاسو دپاره بهتره ده چې زۀ لاړ شم. ځکه کۀ زۀ لاړ نۀ شم نو مددګار به تاسو ته رانۀ شى خو کۀ زۀ لاړ شم نو هغه به زۀ تاسو له راولېږم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25607, 'John 16:8', 'John', 16, 8, '&nbsp;او کله چې هغه راشى نو هغه به دُنيا د ګناه او د صداقت او اِنصاف په باب کښې ملامته کړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25608, 'John 16:9', 'John', 16, 9, '&nbsp;د ګناه په باب کښې ځکه چې هغوئ په ما ايمان نۀ راوړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25609, 'John 16:10', 'John', 16, 10, '&nbsp;د صداقت په باب کښې ځکه چې زۀ پلار له ځم او تاسو به ما نور ونۀ وينئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25610, 'John 16:11', 'John', 16, 11, '&nbsp;او د اِنصاف په باب کښې ځکه چې د دې دُنيا سردار يعنې شېطان مجرم کړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25611, 'John 16:12', 'John', 16, 12, '&nbsp;ما سره نورې هم ډيرې خبرې دى چې تاسو ته يې وکړم خو تاسو اوس دا نۀ شئ برداشت کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25612, 'John 16:13', 'John', 16, 13, '&nbsp;خو چې د حقيقت روح راشى نو هغه به تاسو د حقيقت طرف ته بوځى ځکه چې هغه به د خپله ځانه خبرې نۀ کوى، خو هغه څۀ به وائى څۀ چې د خُدائ پاک نه اورى او تاسو ته به د راتلونکو واقعاتو په حقله پېشګوئې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25613, 'John 16:14', 'John', 16, 14, '&nbsp;هغه به ما ته لوئى راکړى ځکه چې هغه به زما نه هغه څۀ حاصل کړى چې په ما کښې دى او تاسو ته به ووائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25614, 'John 16:15', 'John', 16, 15, '&nbsp;څۀ چې د پلار دى هغه زما دى، په دې وجه ما تاسو ته وفرمائيل چې هغه به ما نه هغه څۀ حاصل کړى څۀ چې په ما کښې دى او تاسو ته به يې وښائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25615, 'John 16:16', 'John', 16, 16, '&nbsp;په لږ ساعت کښې به تاسو نور ما نۀ وينئ او بيا لږ ساعت پس به تاسو ما ووينئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25616, 'John 16:17', 'John', 16, 17, '&nbsp;بيا د هغۀ ځينو مريدانو يو بل ته ووئيل، ”د هغۀ مونږ ته د دې بيان نه څۀ مطلب دے چې په لږ ساعت کښې به تاسو نور ما نۀ وينئ او بيا لږ ساعت پس به تاسو ما ووينئ، او، چې زۀ خپل پلار له روان يم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25617, 'John 16:18', 'John', 16, 18, '&nbsp;هغوئ وئيل چې، ”د هغۀ د دې لږ ساعت نه څۀ مطلب دے؟ مونږ ته پته نشته چې د هغۀ بيان د څۀ په حقله دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25618, 'John 16:19', 'John', 16, 19, '&nbsp;عيسىٰ په دې پوهه شو چې هغوئ له ما نه د تپوسونو په طلب دى نو هغۀ هغوئ ته وفرمائيل، ”ولې تاسو په دې بحث کوئ کوم بيان چې ما تاسو له وکړو چې، په لږ ساعت کښې به تاسو نور ما نۀ وينئ او بيا لږ ساعت پس به تاسو ما ووينئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25619, 'John 16:20', 'John', 16, 20, '&nbsp;نو زۀ تاسو ته رښتيا وايم چې تاسو به ژاړئ او وير به کوئ خو دُنيا به خوشحاله وى. تاسو به په غم کښې ډوب يئ خو ستاسو غم به په خوشحالۍ بدل شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25620, 'John 16:21', 'John', 16, 21, '&nbsp;د ماشوم د پېدا کېدو په وخت کښې ښځه په تکليف کښې وى. خو د ماشوم په پېدا کېدو سره د هغې نه ټول دردونه هېر شى، د دې خوشحالۍ په وجه چې هغې دُنيا ته يو نوے ماشوم راوستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25621, 'John 16:22', 'John', 16, 22, '&nbsp;نو اوس تاسو غمژن يئ خو زۀ به تاسو بيا ووينم او ستاسو زړونه به خوشحاله شى او هيڅوک به ستاسو خوشحالى تاسو نه وانۀ خلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25622, 'John 16:23', 'John', 16, 23, '&nbsp;په هغه ورځ به تاسو زما نه هيڅ خواست نۀ کوئ. زۀ تاسو ته رښتيا وايم، کۀ تاسو زما په نوم د پلار نه څۀ هم وغواړئ، نو هغه به يې درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25623, 'John 16:24', 'John', 16, 24, '&nbsp;تر اوسه پورې تاسو زما په نوم هيڅ نۀ دى غوښتى. وغواړئ نو تاسو له به درکړے شى نو چې ستاسو خوشحالى پوره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25624, 'John 16:25', 'John', 16, 25, '&nbsp;ما تاسو ته دا هر څۀ په مِثالونو کښې بيان کړل. خو وخت راروان دے چې زۀ به تاسو ته نور په مِثالونو کښې خبرې ونۀ کړم خو په ډاګه به درته د پلار په حقله خبرې کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25625, 'John 16:26', 'John', 16, 26, '&nbsp;په هغه ورځ به تاسو زما په نوم غواړئ. زۀ دا نۀ وايم چې زۀ به د پلار نه ستاسو دپاره خواست کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25626, 'John 16:27', 'John', 16, 27, '&nbsp;ځکه چې پلار په خپله تاسو سره مينه کوى، ځکه چې تاسو ما سره مينه کوئ او ستاسو دا ايمان دے چې زۀ د خُدائ پاک د طرف نه راغلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25627, 'John 16:28', 'John', 16, 28, '&nbsp;زۀ د پلار نه دې دُنيا ته راغلے يم او اوس زۀ دُنيا بيا پرېږدم او خپل پلار له ځم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25628, 'John 16:29', 'John', 16, 29, '&nbsp;د هغۀ مريدانو ووئيل، ”ګوره، تۀ اوس په ډاګه لګيا يې او نۀ په مِثالونو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25629, 'John 16:30', 'John', 16, 30, '&nbsp;مونږ اوس پوهيږو چې تۀ د هر څۀ نه خبر يې او د تپوسونو کولو حاجت درنه د چا نشته. هم په دې وجه زمونږ دا ايمان دے چې تۀ د خُدائ پاک د طرفه راغلے يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25630, 'John 16:31', 'John', 16, 31, '&nbsp;عيسىٰ هغوئ ته جواب ورکړو، ”ولې تاسو اوس په ما يقين کوئ څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25631, 'John 16:32', 'John', 16, 32, '&nbsp;ګورئ، وخت راروان دے، بلکې راغلے دے چې تاسو به خوارۀ وارۀ شئ او هر يو به خپلو کورونو ته لاړ شئ او تاسو به ما اېک يواځې پرېږدئ، خو بيا هم زۀ يواځې نۀ يم ځکه چې پلار ما سره دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25632, 'John 16:33', 'John', 16, 33, '&nbsp;ما تاسو ته دا هر څۀ ووئيل نو چې تاسو په ما کښې سلامتيا حاصله کړئ. په دې دُنيا کښې به تاسو زحمتونو سره مخامخ شئ. خو زړَور شئ ځکه چې زۀ په دُنيا غالب شوے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25633, 'John 17:1', 'John', 17, 1, '&nbsp;د دې خبرو کولو نه پس عيسىٰ پاس آسمان ته وکتل او وې فرمائيل، ”پلاره، وخت راغلے دے، خپل زوئ ته لوئى ورکړه نو چې زوئ تا له جلال درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25634, 'John 17:2', 'John', 17, 2, '&nbsp;ځکه چې تا ما ته په ټولو بنى آدمو اختيار راکړے دے چې هغوئ ټولو له تل عُمرى ژوندون ورکړم څوک چې راته تا حواله کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25635, 'John 17:3', 'John', 17, 3, '&nbsp;او تل عُمرى ژوندون دا دے چې هغوئ تا وپېژنى چې صرف تۀ رښتينے خُدائ پاک يې او عيسىٰ مسيح څوک چې تا رالېږلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25636, 'John 17:4', 'John', 17, 4, '&nbsp;ما په زمکه تا له جلال درکړو د هغه کار په ختمولو چې تا ما ته د کولو دپاره حواله کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25637, 'John 17:5', 'John', 17, 5, '&nbsp;نو اے پلاره، اوس تۀ ما له په خپل حضور کښې لوئى راکړه، هغه لوئى چې کومه ما د دُنيا د پېدا کېدو نه اول ستا په حضور کښې لرله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25638, 'John 17:6', 'John', 17, 6, '&nbsp;ما ستا نوم هغوئ ته څرګند کړو کوم خلق چې په دُنيا کښې تاسو ما ته راکړى دى. هغوئ ستا وُو او تا ما له راکړل او هغوئ ستا په کلام عمل کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25639, 'John 17:7', 'John', 17, 7, '&nbsp;اوس هغوئ پوهه شوى دى چې هر څۀ چې تا ما له راکړى دى دا ستا د طرفه دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25640, 'John 17:8', 'John', 17, 8, '&nbsp;ځکه چې ما هغوئ ته هغه کلام ورکړے دے کوم چې تا ما له راکړے دے، او دوئ هغه قبول کړے دے، او هغوئ په حقيقت پوهه شوى دى چې زۀ له تا نه راغلے يم، او د هغوئ په دې ايمان دے چې زۀ تا رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25641, 'John 17:9', 'John', 17, 9, '&nbsp;زۀ د دُنيا دپاره دُعا نۀ کوم خو د هغوئ دپاره دُعا کوم څوک چې تا ما ته په حواله کړى دى ځکه چې هغوئ ستا دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25642, 'John 17:10', 'John', 17, 10, '&nbsp;څۀ چې زما دى هغه ستا دى، او څۀ چې ستا دى هغه زما دى، او په هغوئ کښې زما لوئى څرګنده شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25643, 'John 17:11', 'John', 17, 11, '&nbsp;نور زۀ په دُنيا کښې نۀ پاتې کېږم خو هغوئ په دُنيا کښې دى او زۀ تا ته درروان يم. اے قُدوسه پلاره، د خپل نوم په طاقت د هغوئ حفاظت وکړه څوک چې تا ما له راکړى دى، نو چې هغوئ هم يو موټے شى څنګه چې مونږ دواړه يو يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25644, 'John 17:12', 'John', 17, 12, '&nbsp;ترڅو چې زۀ د هغوئ سره وم ما ستا په نوم د هغوئ حفاظت وکړو کوم چې تا ما له راکړے وو. ما د هغوئ حفاظت وکړو او په هغوئ کښې يو هم هلاک نۀ شو بې له يو نه چې مرګ يې مقرر وو، نو چې د صحيفې ليک پوره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25645, 'John 17:13', 'John', 17, 13, '&nbsp;خو زۀ اوس تا ته درروان يم. چې په دُنيا کښې کله زۀ دوئ سره وم نو ما دوئ ته د دې خبرو بيان وکړو د دې دپاره چې دوئ زما د خوشحالۍ نه معمور شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25646, 'John 17:14', 'John', 17, 14, '&nbsp;ما ستا پېغام هغوئ له ورکړے دے او دُنيا هغوئ نه نفرت کوى ځکه چې هغوئ د دُنيا نۀ دى لکه څنګه چې زۀ د دُنيا نۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25647, 'John 17:15', 'John', 17, 15, '&nbsp;زۀ ستا نه دا خواست نۀ کوم چې دوئ د دې دُنيا نه وباسى بلکې ستا نه دا خواست کوم چې دوئ د شېطان نه محفوظ وساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25648, 'John 17:16', 'John', 17, 16, '&nbsp;دوئ د دُنيا نۀ دى لکه څنګه چې زۀ د دُنيا نۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25649, 'John 17:17', 'John', 17, 17, '&nbsp;دوئ د حقيقت په وسيله مقدس کړه، ستا کلام حقيقت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25650, 'John 17:18', 'John', 17, 18, '&nbsp;لکه څنګه چې تا زۀ دُنيا ته رالېږلے يم نو دغه شان ما دوئ دُنيا ته لېږلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25651, 'John 17:19', 'John', 17, 19, '&nbsp;او د دوئ دپاره زۀ خپل ځان مقدس کوم نو چې دوئ هم په حقيقت کښې مقدس شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25652, 'John 17:20', 'John', 17, 20, '&nbsp;خو زۀ صرف د دوئ دپاره دُعا نۀ غواړم بلکې د هغه چا دپاره هم څوک چې د دوئ د کلام په وسيله به په ما ايمان راوړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25653, 'John 17:21', 'John', 17, 21, '&nbsp;چې هغوئ هم يو موټے شى، اے پلاره، لکه څنګه چې تۀ او زۀ يو يُو. نو دغه شان دې دوئ هم په مونږ کښې يو وى، چې دُنيا په دې يقين وکړى چې زۀ تا رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25654, 'John 17:22', 'John', 17, 22, '&nbsp;کومه لوئى چې تا ما له راکړې ده هغه ما دوئ له ورکړه د دې دپاره چې دوئ يو وى لکه چې مونږ يو يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25655, 'John 17:23', 'John', 17, 23, '&nbsp;زۀ په هغوئ کښې يم او تۀ په ما کښې يې، چې دوئ په مکمل توګه يو شى. بيا چې دُنيا په دې پوهه شى چې زۀ تا رالېږلے يم، او تا د دوئ سره هم داسې مينه وکړله لکه چې ما سره دې کوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25656, 'John 17:24', 'John', 17, 24, '&nbsp;اے پلاره، هغه خلق څوک چې تا ما له راکړى دى زۀ غواړم چې دوئ هم ما سره وى چرته چې زۀ يم، چې دوئ زما لوئى ووينى کومه چې تا ما له راکړې ده ځکه چې تا د دُنيا د پېدا کېدو نه مخکښې ما سره مينه کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25657, 'John 17:25', 'John', 17, 25, '&nbsp;اے صادقه پلاره، دُنيا تا نۀ پېژنى خو زۀ تا پېژنم او دوئ ته پته ده چې تا زۀ رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25658, 'John 17:26', 'John', 17, 26, '&nbsp;ما ستا نوم دوئ ته څرګند کړو او دا به لا نور هم څرګندوم د دې دپاره چې کومه مينه چې تا ما سره کوله، هغه دې په دوئ کښې هم وى، او زۀ دې هم په دوئ کښې يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25659, 'John 18:1', 'John', 18, 1, '&nbsp;د دې خبرو نه پس عيسىٰ د خپلو مريدانو سره بهر ووتو او د قِدرون د وادۍ نه پورې وتلو. هلته يو باغ وو چې عيسىٰ او د هغۀ مريدان په کښې ورننوتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25660, 'John 18:2', 'John', 18, 2, '&nbsp;نو يهوداه، څوک چې به د هغۀ مُخبرى کوى، هغۀ ته د هغه ځائ هم پته وه ځکه چې عيسىٰ به اکثر د خپلو مريدانو سره هلته مِلاوېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25661, 'John 18:3', 'John', 18, 3, '&nbsp;نو يهوداه د فريسيانو او مشرانو اِمامانو له خوا د رومى آفسر وسله بنده دسته او محافظان ډيوې او مشعلونه په لاس هغه ځائ ته راغلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25662, 'John 18:4', 'John', 18, 4, '&nbsp;عيسىٰ په دې پوهېدو چې څۀ به ورسره کيږى خو بيا هم ور مخکښې شو او هغوئ نه يې تپوس وکړو چې، ”تاسو څوک لټوئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25663, 'John 18:5', 'John', 18, 5, '&nbsp;هغوئ جواب ورکړو چې، ”عيسىٰ ناصرى.“ عيسىٰ وفرمائيل، ”زۀ هغه يم.“ او يهوداه چا چې د هغۀ مُخبرى وکړه د هغوئ سره ولاړ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25664, 'John 18:6', 'John', 18, 6, '&nbsp;کله چې عيسىٰ هغوئ ته وفرمائيل چې، ”زۀ هغه يم،“ نو هغوئ وروستو شول او په زمکه پرېوتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25665, 'John 18:7', 'John', 18, 7, '&nbsp;عيسىٰ بيا هغوئ نه تپوس وکړو، ”دا تاسو څوک لټوئ؟“ او هغوئ جواب ورکړو، ”عيسىٰ ناصرى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25666, 'John 18:8', 'John', 18, 8, '&nbsp;عيسىٰ ورته وفرمائيل، ”ما تاسو ته وفرمائيل چې هغه زۀ يم. کۀ تاسو ما لټوئ نو دا نور سړى پرېږدئ چې ځى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25667, 'John 18:9', 'John', 18, 9, '&nbsp;دا د هغۀ د هغه خبرو پوره کول وُو چې هغۀ فرمائيلى وُو، ”چې ما د هغوئ نه يو کس هم نۀ دے ضائع کړے څوک چې تا ما ته حواله کړى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25668, 'John 18:10', 'John', 18, 10, '&nbsp;نو شمعون پطروس خپله تُوره راويستله او د مشر اِمام په غلام يې ګزار وکړو او ښے غوږ يې ترې نه پرې کړو. د غلام نوم ملخوس وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25669, 'John 18:11', 'John', 18, 11, '&nbsp;عيسىٰ پطروس ته وفرمائيل چې، ”خپله تُوره واپس په تيکى کښې کېږده. ولې زۀ هغه پياله ونۀ څښم چې پلار ما ته راکړې ده؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25670, 'John 18:12', 'John', 18, 12, '&nbsp;نو د سپاهيانو دستې سره د خپل آفسر او يهودى محافظانو او مشرانو عيسىٰ ونيولو او وې تړلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25671, 'John 18:13', 'John', 18, 13, '&nbsp;هغوئ هغه اول اناس ته بوتلو، اناس د کائفس سخر وو څوک چې د هغه کال دپاره مشر اِمام وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25672, 'John 18:14', 'John', 18, 14, '&nbsp;کائفس هغه سړے وو چا چې يهوديانو ته دا مشوره ورکړې وه چې دا بهتره ده چې يو سړے د ټول قوم دپاره مړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25673, 'John 18:15', 'John', 18, 15, '&nbsp;شمعون پطروس او يو بل مريد په عيسىٰ پسې وروستو روان وُو او د هغه بل مريد د مشر اِمام سره تعلق وو نو ځکه هغه د عيسىٰ سره د مشر اِمام دربار ته ورننوتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25674, 'John 18:16', 'John', 18, 16, '&nbsp;خو پطروس د دروازې نه بهر ايسار شو. نو هغه بل مريد چې د مشر اِمام سره يې تعلق وو، واپس بهر راوتو او د هغه ښځې سره يې خبرې وکړې چې د دروازې چوکيداره وه او پطروس يې دننه راوستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25675, 'John 18:17', 'John', 18, 17, '&nbsp;ښځې پطروس ته ووئيل، ”آيا تۀ هم د دې سړى مريد نۀ يې څۀ؟“ پطروس ووئيل چې، ”نه، زۀ نۀ يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25676, 'John 18:18', 'John', 18, 18, '&nbsp;نوکرانو او محافظانو د سکارو اور بل کړے وو ځکه چې يخنى وه او هغوئ ترې چاپېره ولاړ وُو او ځانونه يې تودول. او پطروس هم د هغوئ سره ولاړ وو او ځان يې تودولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25677, 'John 18:19', 'John', 18, 19, '&nbsp;بيا مشر اِمام د عيسىٰ نه د هغۀ د مريدانو او د هغۀ د تعليم په حقله تپوس وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25678, 'John 18:20', 'John', 18, 20, '&nbsp;عيسىٰ جواب ورکړو چې، ”ما دُنيا ته په ډاګه خبرې کړې دى. ما همېشه په عبادتخانو او د خُدائ په کور کښې تعليم ورکړے دے چرته چې ټول يهوديان راغونډيږى او ما په پټه څۀ هم نۀ دى وئيلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25679, 'John 18:21', 'John', 18, 21, '&nbsp;نو تۀ زما نه تپوسونه ولې کوې؟ هغوئ نه تپوس وکړه چا چې هغه اورېدلى دى څۀ چې ما هغوئ ته وئيلى دى، هغوئ ته پته ده چې ما څۀ وئيلى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25680, 'John 18:22', 'John', 18, 22, '&nbsp;کله چې عيسىٰ دا وفرمائيل نو يو محافظ چې د هغۀ په خوا کښې ولاړ وو عيسىٰ ته يې په مخ څپېړه ورکړه او وې وئيل، ”مشر اِمام ته څوک داسې جواب ورکوى څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25681, 'John 18:23', 'John', 18, 23, '&nbsp;عيسىٰ جواب ورکړو، ”کۀ بد مې وئيلى وى نو په ما يې ثابته کړه، خو کۀ مې ټيک خبره کړې وى نو څپېړه دې ولې راکړه؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25682, 'John 18:24', 'John', 18, 24, '&nbsp;بيا اناس عيسىٰ مشر اِمام کائفس ته تړلے ولېږلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25683, 'John 18:25', 'John', 18, 25, '&nbsp;په دې دوران کښې شمعون پطروس ولاړ وو او خپل ځان يې تودولو، نو هغوئ ترې تپوس وکړو، ”ولې تۀ هم د هغۀ د مريدانو نه يو نۀ يې څۀ؟“ هغۀ اِنکار وکړو او وې وئيل چې، ”نه، زۀ نۀ يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25684, 'John 18:26', 'John', 18, 26, '&nbsp;د مشر اِمام يو غلام چې د هغه سړى خپلوان وو د چا نه چې پطروس غوږ پرې کړے وو ورنه تپوس وکړو، ”ما تۀ د هغۀ سره په باغ کښې نۀ وې ليدلے څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25685, 'John 18:27', 'John', 18, 27, '&nbsp;پطروس بيا اِنکارى شو او چرګ په هم هغه وخت کښې بانګ ووئيلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25686, 'John 18:28', 'John', 18, 28, '&nbsp;بيا هغوئ عيسىٰ سحر وختى د کائفس د کور نه د رومى ګورنر قلعې ته بوتلو. نو يهوديان د قلعې نه بهر ودرېدل ځکه چې هغوئ غوښتل چې خپل ځانونه د پليتۍ نه وساتى دې دپاره چې د فسح خوراک نه منع نۀ کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25687, 'John 18:29', 'John', 18, 29, '&nbsp;نو پيلاطوس ورته بهر راووتو او تپوس يې ترې وکړو، ”تاسو د دې سړى خلاف څۀ اِلزام لګوئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25688, 'John 18:30', 'John', 18, 30, '&nbsp;هغوئ جواب ورکړو، ”کۀ دا سړے چرې مجرم نۀ وے نو مونږ به تا له نۀ راوستو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25689, 'John 18:31', 'John', 18, 31, '&nbsp;پيلاطوس هغوئ ته ووئيل، ”دے بوځئ او د خپل شريعت په مطابق يې فېصله وکړئ.“ يهوديانو جواب ورکړو چې، ”مونږ ته دا اجازت نشته چې څوک مړ کړُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25690, 'John 18:32', 'John', 18, 32, '&nbsp;او دغه شان د عيسىٰ هغه خبره پوره شوه چې هغه به په کوم قسمه مرګ مړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25691, 'John 18:33', 'John', 18, 33, '&nbsp;نو پيلاطوس واپس قلعې ته ننوتو او عيسىٰ يې راوغوښتو او د هغۀ نه يې تپوس وکړو چې، ”تۀ د يهوديانو بادشاه يې څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25692, 'John 18:34', 'John', 18, 34, '&nbsp;عيسىٰ جواب ورکړو، ”دا تپوس تۀ په خپله ما نه کوې، يا کۀ بل چا درته زما په حقله وئيلى دى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25693, 'John 18:35', 'John', 18, 35, '&nbsp;پيلاطوس ووئيل، ”زۀ يهودى يم څۀ؟ ستا خپل قام او مشرانو اِمامانو تۀ ما ته په حواله کړے يې. تا څۀ کړى دى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25694, 'John 18:36', 'John', 18, 36, '&nbsp;عيسىٰ جواب ورکړو، ”زما بادشاهى د دې دُنيا بادشاهى نۀ ده. کۀ چرې زما بادشاهى د دې دُنيا وے، نو زما خادِمانو به د يهوديانو نه زما د بچ کولو دپاره د هغوئ سره جنګ کړے وے. خو زما بادشاهى د دې دُنيا نۀ ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25695, 'John 18:37', 'John', 18, 37, '&nbsp;پيلاطوس هغۀ ته ووئيل، ”نو تۀ بادشاه يې؟“ عيسىٰ جواب ورکړو چې، ”تۀ وائې چې زۀ بادشاه يم. آو، زۀ د دې دپاره پېدا شوے يم، او د دې دپاره زۀ دُنيا ته راغلے يم چې د حقيقت ګواهى ورکړم. او هر څوک چې حقيقت خوښوى هغه زما آواز اورى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25696, 'John 18:38', 'John', 18, 38, '&nbsp;پيلاطوس هغۀ ته ووئيل، ”حقيقت څۀ دے؟“ په حضرت عيسىٰ د مرګ فتوىٰ دې نه پس هغه بيا يهوديانو له بهر ورووتو او هغوئ ته يې ووئيل چې، ”ما د دۀ خلاف هيڅ جرم پېدا نۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25697, 'John 18:39', 'John', 18, 39, '&nbsp;خو ستاسو دا رِواج دے چې زۀ يو قېدى د فسح اختر په ورځ ستاسو دپاره آزادوم. ستاسو دا خوښه ده چې زۀ د يهوديانو بادشاه درته آزاد کړم څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25698, 'John 18:40', 'John', 18, 40, '&nbsp;خو په جواب کښې خلقو چغې کړلې، ”نه، دا سړے نه، خو برابا آزاد کړه.“ او برابا يو ډاکو وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25699, 'John 19:1', 'John', 19, 1, '&nbsp;بيا پيلاطوس عيسىٰ بوتلو او په کوړو يې ووهلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25700, 'John 19:2', 'John', 19, 2, '&nbsp;او سپاهيانو د ازغو تاج جوړ کړو او هغۀ ته يې په سر کړو او هغۀ ته يې کاسنى چُوغه ورواغوسته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');